alter table public.municipios alter column geom set not null;
create index idx_municipios_geom on public.municipios using gist (geom);

-- A plaza is the client's grouping of real municipios; geography never points back at the client.
create table public.plaza_municipios (
  plaza_id uuid not null references public.plazas(id) on delete cascade,
  municipio_id integer not null unique references public.municipios(id),
  primary key (plaza_id, municipio_id)
);

alter table public.plaza_municipios enable row level security;

insert into public.plaza_municipios (plaza_id, municipio_id)
select p.id, m.id
from (values
  ('Camiri', '070706'),
  ('Cochabamba', '030101'),
  ('Concepcion', '071101'),
  ('El Alto', '020105'),
  ('La Paz', '020101'),
