  ('Oruro', '040101'),
  ('Potosi', '050101'),
  ('Riberalta', '080201'),
  ('San Ignacio', '070301'),
  ('Santa Cruz de la Sierra', '070101'),
  ('Sucre', '010101'),
  ('Tarija', '060101'),
  ('Trinidad', '080101')
) as v(plaza, codigo_ine)
join public.plazas p on p.nombre = v.plaza
join public.municipios m on m.codigo_ine = v.codigo_ine;

-- Simplified borders can leave a real point a few meters outside every polygon, so the nearest one within ~2 km wins.
create function public.municipio_en_punto(p_latitud double precision, p_longitud double precision) returns integer
  language sql stable
  set search_path = ''
as $$
  select m.id
  from public.municipios m,
    lateral (select extensions.st_setsrid(extensions.st_makepoint(p_longitud, p_latitud), 4326) as punto) p
  where extensions.st_dwithin(m.geom, p.punto, 0.02)
  order by extensions.st_distance(m.geom, p.punto), m.id
  limit 1
$$;

revoke all on function public.municipio_en_punto(double precision, double precision) from public, anon, authenticated;

alter table public.activaciones
  add column municipio_id integer references public.municipios(id),
  add column precision_gps_m real;

create index idx_activaciones_municipio_fecha on public.activaciones using btree (municipio_id, fecha_activacion);

-- SECURITY DEFINER because the app inserts as authenticated, which cannot read municipios.
create function public.ubicar_activacion() returns trigger
  language plpgsql
  security definer
  set search_path = ''
as $$
begin
  new.municipio_id := public.municipio_en_punto(new.latitud, new.longitud);
  if new.municipio_id is not null then
    select coalesce(m.nombre_comun, m.nombre) into new.ciudad_activacion
    from public.municipios m where m.id = new.municipio_id;
  end if;
  return new;
end;
$$;

revoke all on function public.ubicar_activacion() from public, anon, authenticated;

create trigger trg_ubicar_activacion
  before insert or update of latitud, longitud, ciudad_activacion, municipio_id on public.activaciones
  for each row execute function public.ubicar_activacion();

alter table public.activaciones
  add constraint activaciones_coordenadas_check check (latitud is not null and longitud is not null) not valid;
alter table public.activaciones validate constraint activaciones_coordenadas_check;

-- Typed values before the GPS backfill, kept to report and audit the correction.
create table public.activaciones_ciudad_previa (
  activacion_id uuid primary key references public.activaciones(id) on delete cascade,
  ciudad_activacion text
);

alter table public.activaciones_ciudad_previa enable row level security;

insert into public.activaciones_ciudad_previa (activacion_id, ciudad_activacion)
select id, ciudad_activacion from public.activaciones;

update public.activaciones set municipio_id = public.municipio_en_punto(latitud, longitud);
